// Package webassets embeds the production frontend build.
//
// The dist directory is generated by `npm run build` under web/. A committed
// .gitkeep keeps the embed pattern valid before the frontend is built; the
// webui package reports a clear "not built" response in that state. Production
// images always build the frontend first.
package webassets

import (
	"embed"
	"io/fs"
)

//go:embed all:dist
var embedded embed.FS

// Dist returns the built single-page application rooted at index.html.
func Dist() fs.FS {
	sub, err := fs.Sub(embedded, "dist")
	if err != nil {
		panic("webassets: embedded dist is missing: " + err.Error())
	}
	return sub
}
